import sys

# Read the parking lot
with open('/workdir/data/parking.txt', 'r') as f:
    first_line = f.readline().strip()
    n, m = map(int, first_line.split())
    grid = []
    for _ in range(n):
        line = f.readline().strip()
        grid.append(list(line))

# Build prefix sum matrix of empty cells (1 for '.', 0 for '*')
prefix = [[0] * (m + 1) for _ in range(n + 1)]
for i in range(n):
    for j in range(m):
        prefix[i+1][j+1] = prefix[i][j+1] + prefix[i+1][j] - prefix[i][j] + (1 if grid[i][j] == '.' else 0)

# Function to check if rectangle (x1,y1) to (x2,y2) is all empty
def is_empty(x1, y1, x2, y2):
    # x1, y1: top-left, x2, y2: bottom-right (0-indexed, inclusive)
    # sum = prefix[x2+1][y2+1] - prefix[x1][y2+1] - prefix[x2+1][y1] + prefix[x1][y1]
    total = prefix[x2+1][y2+1] - prefix[x1][y2+1] - prefix[x2+1][y1] + prefix[x1][y1]
    return total == (x2 - x1 + 1) * (y2 - y1 + 1)

# Precompute results
result = [[0] * m for _ in range(n)]

for i in range(1, n + 1):
    for j in range(1, m + 1):
        count = 0
        for x in range(n - i + 1):
            for y in range(m - j + 1):
                if is_empty(x, y, x + i - 1, y + j - 1):
                    count += 1
        result[i-1][j-1] = count

# Write output
with open('/workdir/answer.txt', 'w') as f:
    for i in range(n):
        for j in range(m):
            f.write(f"{result[i][j]} ")
        f.write('\n')

print("Done!")
